			{title:"情感",id:41},
			{title:"杂谈",id:42},
			{title:"鬼话",id:43},
			{title:"历史",id:34},
			{title:"武侠",id:2},
			{title:"当代",id:24},
			{title:"商道",id:47},
			{title:"杂文",id:21},
			{title:"文学",id:8},
			{title:"传记",id:11},
			{title:"军事",id:45},
			{title:"中国",id:27},
			{title:"政治",id:30},
			{title:"社会",id:28},
			{title:"纪实",id:25},
			{title:"官场",id:13},
			{title:"文化",id:20},
			{title:"战争",id:37},
			{title:"现代",id:36},
			{title:"逻辑",id:18},
			{title:"创业",id:16}
		]
	},
	{
		title:"🌀白马楼🌀",
		categories:[
			{title:"私密",id:6,host:"{{host1}}"},
			{title:"精品",id:23,host:"{{host1}}"}
		]
	}
];
sections.forEach(section=>{
	push(section.title,"",1,1);
	section.categories.forEach(category=>{
		const baseHost=category.host||host;
		const url=`${baseHost}/rank/month/${category.id}/{{page}}.html`;
		push(category.title,url)
	});
});
JSON.stringify(sort)

